// FUNCTION: BFME2 0x0054D74B size=151 name=?findLadder@LadderList@@QAEPBVLadderInfo@@ABVAsciiString@@G@Z evidence=N:ledger tier=B hypothesis:name:Z
const LadderInfo *LadderList::findLadder(const AsciiString &addr, UnsignedShort port)
{
	LadderInfoList::const_iterator cit;

	for (cit = m_specialLadders.begin(); cit != m_specialLadders.end(); ++cit)
	{
		const LadderInfo *li = *cit;
		if (li->address == addr && li->port == port)
			return li;
	}

	for (cit = m_standardLadders.begin(); cit != m_standardLadders.end(); ++cit)
	{
		const LadderInfo *li = *cit;
		if (li->address == addr && li->port == port)
			return li;
	}

	for (cit = m_localLadders.begin(); cit != m_localLadders.end(); ++cit)
	{
		const LadderInfo *li = *cit;
		if (li->address == addr && li->port == port)
			return li;
	}

	return 0;
}

// FUNCTION: BFME2 0x0054DA41 size=2234 name=?parseLadder@@YAPAVLadderInfo@@VAsciiString@@@Z evidence=N:ledger tier=B hypothesis:Z

// FUNCTION: BFME2 0x0054E2FB size=299 name=?checkLadder@LadderList@@AAEXVAsciiString@@H@Z evidence=N:ledger tier=B hypothesis:K
void LadderList::checkLadder(AsciiString fname, Int index)
{
	File *fp = TheFileSystem->openFile(fname.str(), File::READ | File::TEXT);
	char buf[1024];
	AsciiString rawData;
	if (fp)
	{
		Int len;
		while (!fp->eof())
		{
			len = fp->read(buf, 1023);
			buf[len] = 0;
			buf[1023] = 0;
			rawData.concat(buf);
		}
		fp->close();
		fp = 0;
	}

	if (rawData.isEmpty())
		return;

	LadderInfo *li = parseLadder(rawData);
	if (!li)
		return;

	if (li->address.isEmpty())
	{
		delete li;
		return;
	}

	if (!li->port)
	{
		delete li;
		return;
	}

	if (li->validMaps.size() == 0)
	{
		delete li;
		return;
	}

	li->index = index;
	li->validQM = false;
	li->validCustom = false;

	m_localLadders.push_back(li);
}

// FUNCTION: BFME2 0x0054E426 size=288 name=?loadLocalLadders@LadderList@@AAEXXZ evidence=N:ledger tier=B hypothesis:K

// FUNCTION: BFME2 0x0054E546 size=592 name=??0LadderList@@QAE@XZ evidence=N:ledger tier=B hypothesis:K
LadderList::LadderList()
{
	AsciiString rawMotd = TheGameSpyConfig->getLeftoverConfig();
	AsciiString line;
	Bool inLadders = false;
	Bool inSpecialLadders = false;
	Bool inLadder = false;
	LadderInfo *lad = 0;
	Int index = 1;
	AsciiString rawLadder;

	while (rawMotd.nextToken(&line, "\n"))
	{
		if (line.getCharAt(line.getLength() - 1) == '\r')
			line.removeLastChar();

		line.trim();

		if (line.isEmpty())
			continue;

		if (!inLadders && line.compare("<Ladders>") == 0)
		{
			inLadders = true;
			rawLadder.clear();
		}
		else if (inLadders && line.compare("</Ladders>") == 0)
		{
			inLadders = false;
		}
		else if (!inSpecialLadders && line.compare("<SpecialLadders>") == 0)
		{
			inSpecialLadders = true;
			rawLadder.clear();
		}
		else if (inSpecialLadders && line.compare("</SpecialLadders>") == 0)
		{
			inSpecialLadders = false;
		}
		else if (inLadders || inSpecialLadders)
		{
			if (line.startsWith("<Ladder ") && !inLadder)
			{
				inLadder = true;
				rawLadder.clear();
				rawLadder.concat(line);
				rawLadder.concat('\n');
			}
			else if (line.compare("</Ladder>") == 0 && inLadder)
			{
				inLadder = false;
				rawLadder.concat(line);
				rawLadder.concat('\n');
				if ((lad = parseLadder(rawLadder)) != 0)
				{
					lad->index = index++;
					if (inLadders)
						m_standardLadders.push_back(lad);
					else
						m_specialLadders.push_back(lad);
				}
				rawLadder.clear();
			}
			else if (inLadder)
			{
				rawLadder.concat(line);
				rawLadder.concat('\n');
			}
		}
	}

	loadLocalLadders();
}

